/**
 * The shape of Deploy/OURONET-REGISTRY.json.
 *
 * Generated by REPL/tools/_registry.py in the Pact repo, which reads the CHAIN via
 * `describe-module` and falls back to the sources only for modules not yet deployed. So the
 * authority here is what is CALLABLE, not what someone intends to deploy.
 */

/** One parameter, in declaration order. Position is the calling convention. */
export interface Param {
  name: string;
  type: string;
}

/** How a call executes -- see `ExecutionMode`. */
export type ExecutionMode =
  /** the provided inputs suffice; nothing is read off-chain first */
  | "direct"
  /** ONE transaction, but a preflight read supplies some argument */
  | "indirect-single"
  /** a preflight is cut into slices, one per transaction, ORDER-INDEPENDENT */
  | "indirect-parallel"
  /** a preflight reports progress; each call advances a stored cursor. STRICTLY ORDERED */
  | "indirect-sequential"
  /** multi-transaction by CONTINUATION: step 0 on submit, the rest are `cont` payloads */
  | "defpact";

export interface FedParam {
  param: string;
  type: string;
  /** the read(s) that produce this value. A client cannot construct it. */
  producedBy: string[];
  /** for a fed slice, what cuts the preflight's output into per-transaction slices */
  slicedBy: string[] | null;
}

export interface Continuation {
  payload: "cont";
  pactId: string;
  step: string;
  rollback: string;
  /** empty for every defpact in Ouronet: no step reads client input */
  data: Record<string, never>;
  dataNote: string;
  /** the surprise: continuations are NOT gas-sponsored. Step 0 is. */
  gas: string;
}

export interface Execution {
  mode: ExecutionMode;
  shape?: string;
  note: string;
  /** reads to run BEFORE building the transaction */
  preflight?: string[] | null;
  fedParams?: FedParam[] | null;
  preflightUnresolved?: boolean;
  /** defpact only */
  pact?: string;
  steps?: number;
  rollbackSteps?: number;
  inputs?: ExecutionMode;
  continuation?: Continuation;
  /** false when a supported single-transaction twin exists -- see preferInstead */
  supported?: boolean;
  preferInstead?: string;
  supportedNote?: string;
  /** the reader that computes this call's required capabilities */
  capabilityPreflight?: string;
}

export interface OwnershipClause {
  /** the account, or "owner of `<entity>`" when a lookup is needed */
  account: string;
  via: "parameter" | "reader";
  /** ALWAYS = unconditional. CONDITIONAL = binds on one branch only. */
  when: "ALWAYS" | "CONDITIONAL";
  meaning: string;
  reader?: string;
  subject?: string;
  conditionalOn?: string;
}

export interface Ownership {
  resolved: boolean;
  requires?: OwnershipClause[];
  /** subjects found deeper in the call tree that could not be mapped to a parameter */
  unmapped?: string[] | null;
  unmappedNote?: string;
  reason?: string;
}

export interface Sponsorship {
  /** true, false, or "step-0-only" for a defpact whose continuations the customer pays */
  sponsored: boolean | "step-0-only";
  sponsor?: string;
  cap?: string;
  capArgs?: Param[];
  suppliedBy?: string | null;
  conditional?: string | null;
  stepsNote?: string;
}

export interface ExternalCaps {
  required: true;
  /** the READER that computes the capability arguments -- it IS the formula */
  computedBy: string;
  readerParams: Param[];
  /** reader parameter -> this entrypoint's parameter, or a note when client-supplied */
  argsFrom: Record<string, string>;
  returns: string;
  format: string;
  parse: string;
  attachTo: string;
  note: string;
}

/** Where a single ghost value may be used. Absent field = permitted. */
export interface GhostUse {
  /** false = MUST NOT be prefilled into an input that can reach a signed transaction. */
  zbom?: boolean;
  /** false = must not be rendered at all. */
  tooltip?: boolean;
  /** render this string instead of the value (the submittable and readable forms differ). */
  display?: string;
}

export interface Ghost {
  /** example arguments by parameter name. `null` means "obtain from the preflight". */
  args: Record<string, unknown>;
  source: string;
  notes?: Record<string, string>;
  /**
   * Per-parameter surface restrictions. Present ONLY for parameters that have one -- 6 of 423
   * entrypoints today, all guard-taking. An absent parameter is unrestricted.
   */
  use?: Record<string, GhostUse>;
  useNote?: string;
  unresolved?: string[];
  unresolvedNote?: string;
  warning: string;
}

export interface Entrypoint {
  params: Param[];
  /** declared return type, or null when the signature does not pin one */
  returns: string | null;
  returnsNote?: string;
  source: "deployed" | "repo-only";
  modulePath: string;
  moduleHash?: string;
  callable?: false;
  note?: string;
  ownership: Ownership;
  sponsorship: Sponsorship;
  execution: Execution;
  externalCaps?: ExternalCaps;
  ghost: Ghost;
  /** the INFO_ reader that prices this call */
  preview?: string;
  previewVia?: string;
  previewMissing?: string;
}

export interface Preview {
  params: Param[];
  returns: string | null;
  source: "deployed" | "repo-only";
  modulePath: string;
  moduleHash?: string;
}

export interface Divergence {
  module: string;
  function: string;
  deployed: Param[] | null;
  repo: Param[] | null;
}

export interface RegistryDoc {
  note: string;
  namespace: string;
  generatedFrom: "chain+repo" | "repo-only";
  entrypoints: Record<string, Entrypoint>;
  previews: Record<string, Preview>;
  /** bare names that resolve to more than one module -- ALWAYS address MODULE.function */
  nameCollisions: Record<string, { module: string; mode: ExecutionMode }[]>;
  divergences: Divergence[];
  notDeployed: string[];
  surfaceHash: string;
}
